// Declarar el método
public static void saludar() {
    System.out.println("Hola, Java");
}
// Invocarlo desde main
saludar();

public static int sumar(int a, int b) {
    int suma = a + b;
    return suma;
}

public static void mostrarSuma(int a, int b) {
    System.out.println("Suma: " + (a + b));
}

// Uso
mostrarSuma(3, 4);          // imprime: Suma: 7

public static int multiplicar(int a, int b) {
    return a * b;
}

// Uso
int resultado = multiplicar(4, 5); // resultado = 20

// 1-2. Declarar + parámetros
public static int restar(int a, int b) {
    return a - b;          // 3-4. Cuerpo + return
}
// 5. Invocar
int r = restar(9, 4);       // r = 5

